void set(juce::AudioProcessorValueTreeState&s,const char*id,float v){auto*p=s.getParameter(id);if(!p)std::exit(2);p->setValueNotifyingHost(p->convertTo0to1(v));}
float renderDefaultMaxImpulse()
{
    constexpr int sampleRate=44100,blockSize=512,totalSamples=sampleRate*5,warmup=sampleRate;
    CartridgeEngineAudioProcessor processor;processor.setRateAndBufferSizeDetails(sampleRate,blockSize);processor.prepareToPlay(sampleRate,blockSize);
    juce::AudioBuffer<float> buffer(2,blockSize);juce::MidiBuffer midi;float previous2=0,previous1=0,maxImpulse=0;
    for(int offset=0;offset<totalSamples;offset+=blockSize){const auto count=std::min(blockSize,totalSamples-offset);buffer.setSize(2,count,false,false,true);for(int i=0;i<count;++i){const auto sample=.14f*std::sin(juce::MathConstants<float>::twoPi*997.0f*(float)(offset+i)/(float)sampleRate);buffer.setSample(0,i,sample);buffer.setSample(1,i,sample);}processor.processBlock(buffer,midi);for(int i=0;i<count;++i){const auto current=buffer.getSample(0,i);if(offset+i>=warmup)maxImpulse=std::max(maxImpulse,std::abs(current-2.0f*previous1+previous2));previous2=previous1;previous1=current;}}
    return maxImpulse;
}
float renderPresetTransitionMaxImpulse()
{
    constexpr int sampleRate=44100,blockSize=512,totalSamples=sampleRate*5,warmup=sampleRate;
    CartridgeEngineAudioProcessor processor;processor.setRateAndBufferSizeDetails(sampleRate,blockSize);processor.prepareToPlay(sampleRate,blockSize);auto& state=processor.getAPVTS();
    juce::AudioBuffer<float> buffer(2,blockSize);juce::MidiBuffer midi;float previous2=0,previous1=0,maxImpulse=0;bool changed=false;int maxIndex=-1,changeIndex=-1;
    for(int offset=0;offset<totalSamples;offset+=blockSize){if(!changed&&offset>=sampleRate*2){set(state,"codecMode",1);set(state,"speakerModel",3);set(state,"quality",.28f);set(state,"codec",.32f);set(state,"grit",.62f);set(state,"noise",.06f);set(state,"macroLink",1);processor.materialiseLegacyMacros();changed=true;changeIndex=offset;}const auto count=std::min(blockSize,totalSamples-offset);buffer.setSize(2,count,false,false,true);for(int i=0;i<count;++i){const auto sample=.14f*std::sin(juce::MathConstants<float>::twoPi*997.0f*(float)(offset+i)/(float)sampleRate);buffer.setSample(0,i,sample);buffer.setSample(1,i,sample);}processor.processBlock(buffer,midi);for(int i=0;i<count;++i){const auto current=buffer.getSample(0,i);if(offset+i>=warmup){const auto impulse=std::abs(current-2.0f*previous1+previous2);if(impulse>maxImpulse){maxImpulse=impulse;maxIndex=offset+i;}}previous2=previous1;previous1=current;}}
    std::cout<<"Cartridge transition peak offset: "<<(maxIndex-changeIndex)<<" samples\n";
    return maxImpulse;
}
float renderEditorPresetDifference(int selectedId,juce::String&name,bool&materialised)
{
    constexpr int sampleRate=44100,blockSize=512,totalSamples=sampleRate;
    CartridgeEngineAudioProcessor processor;std::unique_ptr<juce::AudioProcessorEditor> editor(processor.createEditor());juce::ComboBox* selector=nullptr;for(int i=0;i<editor->getNumChildComponents();++i)if(auto*box=dynamic_cast<juce::ComboBox*>(editor->getChildComponent(i));box&&box->getNumItems()>10){selector=box;break;}if(!selector)return -1;selector->setSelectedId(selectedId,juce::sendNotificationSync);name=selector->getText();materialised=!processor.legacyMacrosActive();processor.setRateAndBufferSizeDetails(sampleRate,blockSize);processor.prepareToPlay(sampleRate,blockSize);juce::AudioBuffer<float>audio(2,totalSamples);for(int i=0;i<totalSamples;++i){const auto x=.14f*std::sin(juce::MathConstants<float>::twoPi*997.0f*(float)i/(float)sampleRate);audio.setSample(0,i,x);audio.setSample(1,i,x);}juce::MidiBuffer midi;for(int offset=0;offset<totalSamples;offset+=blockSize){const auto count=std::min(blockSize,totalSamples-offset);juce::AudioBuffer<float>view(audio.getArrayOfWritePointers(),2,offset,count);processor.processBlock(view,midi);}double difference=0;for(int i=sampleRate/4;i<totalSamples;++i){const auto input=.14f*std::sin(juce::MathConstants<float>::twoPi*997.0f*(float)i/(float)sampleRate);difference+=std::abs(audio.getSample(0,i)-input);}return(float)(difference/(totalSamples-sampleRate/4));
}
